package main
import("encoding/json";"net/http";"net/http/httptest";"path/filepath";"testing";"time";"os")
func TestNoReplayAfterRestart(t *testing.T){calls:=0;srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){calls++;var c map[string]any;json.NewDecoder(r.Body).Decode(&c);json.NewEncoder(w).Encode(map[string]any{"confirmed":true,"command_id":c["command_id"]})}));defer srv.Close();cfg:=Config{Journal:filepath.Join(t.TempDir(),"journal.json"),Devices:map[string]Device{"device":{URL:srv.URL}}};a:=&Agent{config:cfg,client:srv.Client(),executed:map[string]string{}};cmd:=Command{ID:"test-command",DeviceID:"device",ExpiresAt:time.Now().Add(time.Minute)};if a.execute(cmd)!="confirmed"{t.Fatal("expected acknowledgment")};persisted,err:=os.ReadFile(cfg.Journal);if err!=nil{t.Fatal(err)};restarted:=&Agent{config:cfg,client:srv.Client(),executed:map[string]string{}};if err=json.Unmarshal(persisted,&restarted.executed);err!=nil{t.Fatal(err)};restarted.execute(cmd);if calls!=1{t.Fatal("command executed twice after restart")};cmd.ID="expired";cmd.ExpiresAt=time.Now().Add(-time.Second);a.execute(cmd);if calls!=1{t.Fatal("expired command executed")}}
func TestUnknownNeverRetried(t *testing.T){calls:=0;srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){calls++;w.Write([]byte(`{}`))}));defer srv.Close();a:=&Agent{config:Config{Journal:filepath.Join(t.TempDir(),"journal.json"),Devices:map[string]Device{"device":{URL:srv.URL}}},client:srv.Client(),executed:map[string]string{}};cmd:=Command{ID:"unknown",DeviceID:"device",ExpiresAt:time.Now().Add(time.Minute)};if a.execute(cmd)!="unknown"{t.Fatal("missing acknowledgment must remain unknown")};a.execute(cmd);if calls!=1{t.Fatal("unknown command repeated")}}
